const ATU_ROUTE_DATA={reviewed:'10 de noviembre de 2026',portal:'https://portal.atu.gob.pe/QR/',routes:TRANSIT_CATALOG};
const NETWORK_NAMES={metro:'Metropolitano',azul:'Corredor Azul',rojo:'Corredor Rojo',morado:'Corredor Morado'};
let liveRouteId='B',liveDirection='south',liveStation='Naranjal',liveSimulation=true,simRunning=true,simProgress=0,simSpeed=1,simTimer=null;
const routeSelected=()=>TRANSIT_CATALOG.find(r=>r.id===liveRouteId);
function routeStops(r=routeSelected(),dir=liveDirection){return r[dir]||[]}
function routeCorridor(r=routeSelected(),dir=liveDirection){return routeStops(r,dir)}
function changeLiveRoute(id){liveRouteId=id;liveStation=routeStops()[0];simProgress=0;render()}
function changeLiveDirection(dir){liveDirection=dir;liveStation=routeStops()[0];simProgress=0;render()}
function scheduleView(r,dir){const ss=routeStops(r,dir);return `<div class="schedule"><div class="row between"><h3>Horario del servicio</h3>${icon('clock')}</div><p class="small muted">${esc(ss[0])} → ${esc(ss.at(-1))}</p><table><tbody>${['Lunes a viernes','Sábado','Domingo'].map((label,i)=>`<tr><th>${label}</th><td>${esc(r.schedules[dir][i]||'No proporcionado')}</td></tr>`).join('')}</tbody></table><p class="small muted">Formato de 24 horas. Horario de operación; no indica a qué hora llegará un bus a cada parada. Feriados: sin información.</p></div>`}
function routeEvidence(r,dir){return `<section class="card route-sources"><h3>Fuente del recorrido</h3><p>${esc(r.sourceNote)}</p>${r.note?`<p class="source-note">${esc(r.note)}</p>`:''}${r.maps[dir]?`<a href="maps/${r.maps[dir]}.png" target="_blank" rel="noopener">Abrir mapa proporcionado ↗</a>`:''}${r.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${s.label} ↗</a>`).join('')}<a href="${ATU_ROUTE_DATA.portal}" target="_blank" rel="noopener">Consultar portal ATU ↗</a></section>`}
function simPoint(i,n){const f=i/Math.max(1,n-1);return {x:115+Math.sin(f*Math.PI*3)*48+f*55,y:60+f*360}}
function simMap(r,dir){const ss=routeStops(r,dir),pts=ss.map((_,i)=>simPoint(i,ss.length)),path=pts.map(p=>`${p.x},${p.y}`).join(' ');return `<div class="simulation-map"><svg viewBox="0 0 390 480" role="img" aria-label="Mapa esquemático de ${esc(r.name)}, simulación sin GPS"><defs><pattern id="city-blocks" width="65" height="55" patternUnits="userSpaceOnUse" patternTransform="rotate(-12)"><rect x="5" y="5" width="49" height="39" rx="7" fill="#e0e9e5"/></pattern></defs><rect width="390" height="480" fill="#f0f5f2"/><rect width="390" height="480" fill="url(#city-blocks)"/><path d="M0 240 Q90 330 45 480H0Z" fill="#c7e3e8"/><polyline points="${path}" stroke="white" stroke-width="14" fill="none" stroke-linejoin="round"/><polyline points="${path}" stroke="${r.color}" stroke-width="5" fill="none" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="${i===0||i===pts.length-1?7:3}" stroke="${r.color}" stroke-width="2" fill="white"/>`).join('')}<text x="20" y="26" fill="#47635e" font-size="11">ESQUEMA SIN ESCALA · NO ES GPS</text><text x="${pts[0].x+14}" y="${pts[0].y+4}" fill="#173b4a" font-size="11">${esc(ss[0])}</text><text x="${pts.at(-1).x+12}" y="${pts.at(-1).y+20}" fill="#173b4a" font-size="11">${esc(ss.at(-1))}</text><g id="sim-bus" transform="translate(${pts[0].x},${pts[0].y})"><circle r="20" fill="${r.color}" opacity=".18"/><rect x="-14" y="-12" width="28" height="25" rx="7" fill="#143d51" stroke="white" stroke-width="2"/><rect x="-9" y="-7" width="18" height="10" rx="2" fill="#b7e8e4"/><circle cx="-7" cy="8" r="2" fill="white"/><circle cx="7" cy="8" r="2" fill="white"/></g></svg><span class="sim-tag">${esc(r.name)} · DEMO</span></div>`}
function simulationView(r,dir){return `<section class="card sim-card"><div class="row between"><div><span class="eyebrow muted">SEGUIMIENTO DEL BUS</span><h3 class="spaced">Mira cómo avanza</h3></div><img class="demo-bus-art" src="assets/bus-demo.png" alt="Ilustración de un bus"/></div><label class="demo-switch"><span><strong>Demostración en el mapa</strong><small>Movimiento simulado, sin ubicación real</small></span><input class="switch" type="checkbox" aria-label="Activar simulación del bus" ${liveSimulation?'checked':''} onchange="liveSimulation=this.checked;render()"></label>${liveSimulation?`${simMap(r,dir)}<div class="sim-status"><span class="pill amber">SIMULACIÓN</span><strong id="sim-stop"></strong><p id="sim-next" class="small muted"></p></div><label class="small muted" for="sim-range">Avance del recorrido</label><input id="sim-range" type="range" min="0" max="100" step="0.1" value="${simProgress*100}" oninput="simProgress=Number(this.value)/100;paintSimulation()"><div class="row between sim-controls"><button class="secondary" onclick="simRunning=!simRunning;this.textContent=simRunning?'Pausar':'Reanudar'">${simRunning?'Pausar':'Reanudar'}</button><button class="text-btn" onclick="simProgress=0;paintSimulation()">Reiniciar</button><select aria-label="Velocidad de simulación" onchange="simSpeed=Number(this.value)">${[1,2,4].map(n=>`<option value="${n}" ${simSpeed===n?'selected':''}>${n}×</option>`).join('')}</select></div><p class="small muted">La velocidad es ilustrativa. No representa tiempos de llegada, tráfico ni ocupación.</p>`:'<p class="muted">Simulación desactivada. Puedes seguir consultando paradas y horarios.</p>'}</section>`}
function paintSimulation(){const bus=document.getElementById('sim-bus');if(!bus)return;const ss=routeStops(),pos=simProgress*(ss.length-1),i=Math.min(ss.length-1,Math.floor(pos)),a=simPoint(i,ss.length),b=simPoint(Math.min(i+1,ss.length-1),ss.length),f=pos-i;bus.setAttribute('transform',`translate(${a.x+(b.x-a.x)*f},${a.y+(b.y-a.y)*f})`);document.getElementById('sim-stop').textContent=simProgress===1?'Llegó a '+ss.at(-1):'Desde '+ss[i];document.getElementById('sim-next').textContent=simProgress===1?'Fin del recorrido de demostración.':'Siguiente parada: '+ss[i+1];document.getElementById('sim-range').value=simProgress*100}
function mountSimulation(){clearInterval(simTimer);if(page!=='live'||!liveSimulation)return;paintSimulation();simTimer=setInterval(()=>{if(!simRunning)return;if(simProgress>=1)return;simProgress=Math.min(1,simProgress+0.0015*simSpeed);paintSimulation()},100)}
function liveRouteView(){const r=routeSelected(),stops=routeStops();return heading('Tu ruta, parada a parada.','Consulta los recorridos y horarios. Prueba el avance del bus en modo demostración.')+`<div class="network-tabs">${Object.entries(NETWORK_NAMES).map(([id,n])=>`<button class="chip ${r.network===id?'selected':''}" onclick="changeLiveRoute('${TRANSIT_CATALOG.find(x=>x.network===id).id}')">${n}</button>`).join('')}</div><div class="card route-picker"><div><label for="live-service">Servicio</label><select id="live-service" onchange="changeLiveRoute(this.value)">${TRANSIT_CATALOG.filter(x=>x.network===r.network).map(x=>`<option value="${x.id}" ${r.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div><div><label for="live-direction">Sentido del recorrido</label><select id="live-direction" onchange="changeLiveDirection(this.value)">${['south','north'].map(d=>`<option value="${d}" ${d===liveDirection?'selected':''}>${esc(r[d][0])} → ${esc(r[d].at(-1))}</option>`).join('')}</select></div></div><div class="grid route-layout"><div class="stack"><section class="card"><div class="row between"><span class="pill teal">${r.type}</span><span class="pill">${stops.length} paradas</span></div><h2 class="spaced">${r.name}</h2><p class="muted">${esc(stops[0])} → ${esc(stops.at(-1))}</p>${scheduleView(r,liveDirection)}<button class="primary full spaced" onclick="planFromService('${r.id}','${liveDirection}')">Planificar con este servicio ${icon('arrow')}</button></section><section class="card"><h3>Paradas en orden</h3><p class="small muted">Solo se muestran las paradas del servicio en el sentido elegido.</p><ol class="catalog-stops" style="--route-color:${r.color}">${stops.map((s,i)=>`<li><span>${i+1}</span><div>${esc(s)}${i===0?'<small>Inicio</small>':i===stops.length-1?'<small>Final</small>':''}</div></li>`).join('')}</ol></section></div><div class="stack">${simulationView(r,liveDirection)}${routeEvidence(r,liveDirection)}</div></div>`}
